pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 20 { insertion_sort(arr); return; }
    qsort(arr, 0, len - 1);
}

fn insertion_sort<T: Ord>(arr: &mut [T]) {
    for i in 1..arr.len() {
        let mut j = i;
        while j > 0 && arr[j - 1] > arr[j] { arr.swap(j, j - 1); j -= 1; }
    }
}

fn qsort<T: Ord + Clone>(arr: &mut [T], lo: usize, hi: usize) {
    if hi - lo < 20 { insertion_sort(&mut arr[lo..=hi]); return; }
    let mid = lo + (hi - lo) / 2;
    if arr[lo] > arr[mid] { arr.swap(lo, mid); }
    if arr[lo] > arr[hi] { arr.swap(lo, hi); }
    if arr[mid] > arr[hi] { arr.swap(mid, hi); }
    arr.swap(mid, hi - 1);
    let pivot = arr[hi - 1].clone();
    let mut i = lo + 1;
    let mut j = hi - 2;
    loop {
        while arr[i] < pivot { i += 1; }
        while arr[j] > pivot { if j == 0 { break; } j -= 1; }
        if i >= j { break; }
        arr.swap(i, j);
        i += 1; if j == 0 { break; } j -= 1;
    }
    arr.swap(i, hi - 1);
    if i > lo + 1 { qsort(arr, lo, i - 1); }
    if i + 1 < hi { qsort(arr, i + 1, hi); }
}
